      }
      broker {
        accent_color
        designations
        fulfillment_id
        name
        logo
      }
      email
      fulfillment_id
      href
      mls_set
      name
      nrds_id
      office {
        address {
          city
          coordinate {
            lat
            lon
          }
          country
          line
          postal_code
          state
          state_code
        }
        application_url
        email
        lead_email{
          to
          cc
        }
        fulfillment_id
        hours
        href
        mls_set
        out_of_community
        name
        phones {
          ext
          number
          primary
          trackable
          type
