      county {
        fips_code
        name
        state_code
      }
      city{
        county_needed_for_uniq
      }
      driving_directions
      neighborhoods {
        city
        id
        level
        name
        state_code
      }
      property_address {
        city
        coordinate {
          lat
          lon
