            baths_full_calc
            baths_partial_calc
            beds
            construction
            cooling
            exterior
            fireplace
            garage
            heating
            lot_sqft
            pool
            roofing
            rooms
            sqft
            stories
            styles
            type
            units
            year_built
            year_renovated
